CREATE PROCEDURE SP_Vue_SalesInvoice_DC (@Id Varchar(100)) AS 


BEGIN 


DECLARE @sql1 NVARCHAR(MAX);



SET @sql1 = 'ALTER VIEW Vue_SalesInvoice as SELECT CASE WHEN ordermas.jobno = 0 THEN ''<General>'' + ''/'' + OrderMas.Finyear + ''->'' + OrderMas.BuyOrdNo ELSE RTRIM(CAST(OrderMas.Jobno AS varchar)) + ''/'' + OrderMas.Finyear  END AS OrderNo,  RTRIM(SuppOrdMas.SuppNo) + ''/'' + RTRIM(SuppFyr) as SuppOrder, ordermas.OrdId, OrderMas.BuyOrdNo, Mas_Exporter.ExporterName, Case when isNull(Trs_Salinv.InvType,''Y'') =''Y'' then  Case When Sales_Inv_Yarn_Prefix is Null Or rtrim(Sales_Inv_Yarn_Prefix) ='''' then RTRIM(Trs_Salinv.Invno)  ELSE Rtrim(Sales_Inv_Yarn_Prefix) +''/''+ RTRIM(Trs_Salinv.Invno)  END ELSE  Case when isNull(Trs_Salinv.InvType,''Y'') =''F'' then  Case When Sales_Inv_Fabric_Prefix is Null Or rtrim(Sales_Inv_Fabric_Prefix) ='''' then RTRIM(Trs_Salinv.Invno)  ELSE Rtrim(Sales_Inv_Fabric_Prefix) +''/''+ RTRIM(Trs_Salinv.Invno)   END ELSE Case when isNull(Trs_Salinv.InvType,''Y'') =''A'' then  Case When Sales_Inv_Acc_Prefix is Null Or rtrim(Sales_Inv_Acc_Prefix) ='''' then RTRIM(Trs_Salinv.Invno) ELSE Rtrim(Sales_Inv_Acc_Prefix) +''/''+ RTRIM(Trs_Salinv.Invno)  END END END END  as InvNo , Trs_Salinv.Finyear, Trs_Salinv.Invdt, Trs_Del1.DocNo , StockTable.YF, Mas_Count.CountName, Mas_Color.ColorDesc, Mas_Fabric.Fabdesc, Sum(Trs_Del2.BgRl)BgRl, Sum(Trs_Del2.Kg)Kg,Sum(Trs_Del2.mtr)  as mtr, Trs_Del2.Rate, Trs_Del1.Finyear Dfinyear , Trs_Del1.Dt DCDate, Trs_Salinv.ID, Mas_Exporter.CST ECST, Mas_Exporter.TIN Etin, Mas_Exporter.Phone, Mas_Party.Pname, Mas_Party.Phone PPhone, Mas_Party.CST, Mas_Party.TIN, Mas_Design.DesignDesc, Mas_Buyer.BuyerName, Mas_Buyer.Phone BuyerPhone , Trs_Salinv.PartyType, Mas_Acc.Acc_Descr, (Mas_Exporter.ExporterAddress ) ExporterAddress, Cast(Mas_Party.Paddress as varchar(2000))Paddress, Cast(Mas_Buyer.BuyerAddress as varchar(2000))BuyerAddress,isnull(Mas_PartyState.StateName,'''') PartyState,isnull(Mas_PartyState.StateCode,0)PartyStateCode,isnull(Mas_State.StateName,'''')ExpStateName,Isnull(Mas_State.StateCode,0)ExpStateCode,case when Stocktable.yf=''Y'' then  Mas_HSN.HSNCode else case when Stocktable.yf=''F'' then MAs_HSN2.HSNCode else case when isnull(Acc_PO_HSN_Detail.Hsnid,0)<>0 then (MAs_HSN3.HSNCODE) else (MAs_HSN4.HSNCODE) end end end as  HSNCode, isNull(Mas_Uom.Uom,''KGS'') as UOM,Trs_Del1.EwayBillNo,Trs_Del1.EwayBillDt,Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN (Sum(Trs_Del2.Kg) * trs_del2.Rate) ELSE (Sum(Trs_Del2.mtr) * trs_del2.Rate) END AS Amount,case when Stocktable.yf=''Y'' then case when  isnull(Mas_Exporter.Stateid,0) = isnull(Mas_Party.Stateid,0) then isnull(Trs_Del4.CGSTper,0) else 0 end else case when Stocktable.yf=''F'' then case when  isnull(Mas_Exporter.Stateid,0) = isnull(Mas_Party.Stateid,0) then  isnull(Trs_Del4.CGSTper,0) else 0 end else case  when  isnull(Mas_Exporter.Stateid,0) = isnull(Mas_Party.Stateid,0) then case when isnull(Acc_PO_HSN_Detail.Hsnid,0)<>0 then (MAs_HSN3.NBPercH/2) else(MAs_HSN4.NBPercH/2) end else  0  end  end end as Rate1,case when Stocktable.yf=''Y'' then case when  isnull(Mas_Exporter.Stateid,0) = isnull(Mas_Party.Stateid,0) then isnull(Trs_Del4.SGSTper,0) else 0 end else case when Stocktable.yf=''F'' then  case when  isnull(Mas_Exporter.Stateid,0) = isnull(Mas_Party.Stateid,0) then  isnull(Trs_Del4.SGSTper,0) else 0 end else case when  isnull(Mas_Exporter.Stateid,0) = isnull(Mas_Party.Stateid,0) then case when isnull(Acc_PO_HSN_Detail.Hsnid,0)<>0 then (MAs_HSN3.NBPercH/2) else (MAs_HSN4.NBPercH/2) end else 0 end end end as Rate2,case when Stocktable.yf=''Y'' then case when isnull(Mas_Exporter.Stateid,0) <> isnull(Mas_Party.Stateid,0) then isnull(Trs_Del4.IGSTper,0) else 0 end else case when Stocktable.yf=''F'' then case when  isnull(Mas_Exporter.Stateid,0) <> isnull(Mas_Party.Stateid,0) then isnull(Trs_Del4.IGSTper,0) else 0 end else case when  isnull(Mas_Exporter.Stateid,0) <> isnull(Mas_Party.Stateid,0) then case when isnull(Acc_PO_HSN_Detail.Hsnid,0)<>0 then (MAs_HSN3.NBPercH) else(MAs_HSN4.NBPercH) end else 0 end end end as Rate3,case when Stocktable.yf=''Y'' then case when  isnull(Mas_Exporter.Stateid,0) = isnull(Mas_Party.Stateid,0) then (Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END * Trs_Del4.CGSTper/100)  else 0 end else case when Stocktable.yf=''F'' then case when isnull(Mas_Exporter.Stateid,0) = isnull(Mas_Party.Stateid,0) then (Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END * Trs_Del4.CGSTper/100)  else 0 end else case when  isnull(Mas_Exporter.Stateid,0) = isnull(Mas_Party.Stateid,0) then case when isnull(Acc_PO_HSN_Detail.Hsnid,0)<>0 then ( Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.mtr*trs_del2.rate) END *(MAs_HSN3.NBPercH/2)/100) else(Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.mtr*trs_del2.rate) END *(MAs_HSN4.NBPercH/2)/100) end else 0 end end end as GSTAmount1,case when Stocktable.yf=''Y'' then case when  isnull(Mas_Exporter.Stateid,0) = isnull(Mas_Party.Stateid,0) then (Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END * Trs_Del4.SGSTper/100) else 0 end else case when Stocktable.yf=''F'' then case when  isnull(Mas_Exporter.Stateid,0) = isnull(Mas_Party.Stateid,0) then (Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END * Trs_Del4.SGSTper/100) else 0 end else case when  isnull(Mas_Exporter.Stateid,0) = isnull(Mas_Party.Stateid,0) then case when isnull(Acc_PO_HSN_Detail.Hsnid,0)<>0 then (Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END *(MAs_HSN3.NBPercH/2)/100)  else (Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END *(MAs_HSN4.NBPercH/2)/100)  end else 0 end end end as GSTAmount2,case when Stocktable.yf=''Y'' then case when isnull(Mas_Exporter.Stateid,0) <> isnull(Mas_Party.Stateid,0) then (Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END * Trs_Del4.IGSTper/100) else 0 end else case when Stocktable.yf=''F'' then case when  isnull(Mas_Exporter.Stateid,0) <> isnull(Mas_Party.Stateid,0) then (Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END * Trs_Del4.IGSTper/100) else 0 end else case when  isnull(Mas_Exporter.Stateid,0) <> isnull(Mas_Party.Stateid,0) then case when isnull(Acc_PO_HSN_Detail.Hsnid,0)<>0 then (Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END *(MAs_HSN3.NBPercH)/100)  else(Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END *(MAs_HSN4.NBPercH)/100) end else 0 end end end as Amount3,(Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN (Sum(Trs_Del2.Kg) * trs_del2.Rate) ELSE (Sum(Trs_Del2.Mtr) * trs_del2.Rate) END + case when Stocktable.yf=''Y'' then case when  isnull(Mas_Exporter.Stateid,0) = isnull(Mas_Party.Stateid,0) then (Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END * Trs_Del4.CGSTper/100) else 0 end else case when Stocktable.yf=''F'' then case when  isnull(Mas_Exporter.Stateid,0) = isnull(Mas_Party.Stateid,0) then (Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END * Trs_Del4.CGSTper/100) else 0 end else case when  isnull(Mas_Exporter.Stateid,0) = isnull(Mas_Party.Stateid,0) then case when isnull(Acc_PO_HSN_Detail.Hsnid,0)<>0 then (Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END *(MAs_HSN3.NBPercH/2)/100)  else(Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END *(MAs_HSN4.NBPercH/2)/100) end else 0 end end end + case when Stocktable.yf=''Y'' then case when  isnull(Mas_Exporter.Stateid,0) = isnull(Mas_Party.Stateid,0) then (Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END * Trs_Del4.SGSTper/100) else 0 end else  case when Stocktable.yf=''F'' then case when  isnull(Mas_Exporter.Stateid,0) = isnull(Mas_Party.Stateid,0) then (Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END * Trs_Del4.SGSTper/100) else 0 end else  case when  isnull(Mas_Exporter.Stateid,0) = isnull(Mas_Party.Stateid,0) then case when isnull(Acc_PO_HSN_Detail.Hsnid,0)<>0 then (Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END *(MAs_HSN3.NBPercH/2)/100)  else (Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END *(MAs_HSN4.NBPercH/2)/100)  end else 0 end end end + case when Stocktable.yf=''Y'' then case when  isnull(Mas_Exporter.Stateid,0) <> isnull(Mas_Party.Stateid,0) then  (Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END * Trs_Del4.IGSTper/100) else 0 end else case when Stocktable.yf=''F'' then  case when  isnull(Mas_Exporter.Stateid,0) <> isnull(Mas_Party.Stateid,0) then (Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END * Trs_Del4.IGSTper/100) else 0 end else case when  isnull(Mas_Exporter.Stateid,0) <> isnull(Mas_Party.Stateid,0) then  case when isnull(Acc_PO_HSN_Detail.Hsnid,0)<>0 then (Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END *(MAs_HSN3.NBPercH)/100)  else (Case When isNull(Mas_Uom.Uom,''KGS'')=''KGS'' THEN Sum(Trs_del2.kg*trs_del2.rate) ELSE Sum(Trs_del2.Mtr*trs_del2.rate) END *(MAs_HSN4.NBPercH)/100)   end else 0 end end end  ) as Tot,Mas_Exporter.GSTNo,Mas_Party.GSTNo PGSTNO,case StockTable.yf when ''Y'' then Case when ISNULL(Mas_Color.ColorDesc,'''')='''' then rtrim(Mas_Count.CountName) Else rtrim(Mas_Count.CountName) +''/''+ Mas_Color.ColorDesc End when ''F'' then Case when ISNULL(Mas_Count.CountName,'''')='''' then case when ISNULL(Mas_Color.ColorDesc,'''')='''' then rtrim(Mas_Fabric.Fabdesc) Else case when ISNULL(Mas_Design.DesignDesc,'''') = '''' then rtrim(Mas_Fabric.Fabdesc) + ''/'' + Mas_Color.ColorDesc Else  rtrim(Mas_Fabric.Fabdesc) + ''/'' + Mas_Color.ColorDesc  + ''/'' + Mas_Design.DesignDesc End End Else Case when ISNULL(Mas_Color.ColorDesc,'''')='''' then rtrim(Mas_Fabric.Fabdesc) + ''/'' + Mas_Count.CountName Else Case when ISNULL(Mas_Design.DesignDesc,'''')= '''' then rtrim(Mas_Fabric.Fabdesc) + ''/'' + Mas_Count.CountName + ''/'' + Mas_Color.ColorDesc Else  rtrim(Mas_Fabric.Fabdesc) + ''/'' + Mas_Count.CountName + ''/'' + Mas_Color.ColorDesc + ''/'' + Mas_Design.DesignDesc End End End else Case when ISNULL(Mas_Color.ColorDesc,'''') = '''' then rtrim(Mas_Acc.Acc_Descr) +''/''+ rtrim(Mas_AccDes.AccDescription) Else rtrim(Mas_Acc.Acc_Descr) +''/''+ rtrim(Mas_AccDes.AccDescription)  + ''/'' + Mas_Color.ColorDesc  End end as Descr,isnull(VName,'''')VName,isnull(ReverseCharge,0)ReverseCharge,Isnull(Trs_Salinv.TransPortationMode,'''')TransPortationMode,Mas_Exporter.ExporterAddress As ExpAddress,Mas_Party.Paddress As PartyAddess,IsNull(Mas_Bank.BankName,'''') BankName,IsNull(Mas_Bank.CurrAcc,'''') CurrAcc,IsNull(Mas_Bank.IFSCCode,'''') IFSCCode,isNUll(OrderMas.CostName,'''') as CostName  ,isnull(Mas_AccDes.AccDescription,'''') as AccDescription,ISNULL(Trs_Salinv.Remarks,'''') AS REMARKS    FROM  Trs_Salinv Trs_Salinv INNER JOIN Trs_Del1 Trs_Del1 ON Trs_Salinv.ID=Trs_Del1.InvId INNER JOIN Mas_Exporter Mas_Exporter ON Trs_Salinv.Coycode=Mas_Exporter.ExpID LEFT OUTER JOIN Mas_Buyer Mas_Buyer ON Trs_Salinv.Party=Mas_Buyer.BuyerID LEFT OUTER JOIN Mas_Party Mas_Party ON Trs_Salinv.Party=Mas_Party.PID INNER JOIN Trs_Del2 Trs_Del2 ON Trs_Del1.ID=Trs_Del2.ID INNER JOIN StockTable StockTable ON Trs_Del2.StockID=StockTable.StockID LEFT OUTER JOIN Mas_Fabric Mas_Fabric ON StockTable.FabID=Mas_Fabric.FabID LEFT OUTER JOIN Mas_Count Mas_Count ON StockTable.CntID=Mas_Count.CountID LEFT OUTER JOIN Mas_Color Mas_Color ON StockTable.ColID=Mas_Color.ColID LEFT OUTER JOIN Mas_Design Mas_Design ON StockTable.PRINT_DESIGNID=Mas_Design.DesignId LEFT OUTER JOIN Mas_Acc Mas_Acc ON StockTable.Atype=Mas_Acc.ID LEFT OUTER JOIN Mas_AccDes ON StockTable.Ades  = Mas_AccDes.id  left outer join Mas_State on Mas_State.id=Mas_Exporter.Stateid left outer join mas_state Mas_PartyState on Mas_PartyState.id=Mas_Party.Stateid left outer join Acc_PO_HSN_Detail on Acc_PO_HSN_Detail.Atype=mas_acc.id and Acc_PO_HSN_Detail.Atype=stocktable.atype and Acc_PO_HSN_Detail.Ades=stocktable.Ades and Acc_PO_HSN_Detail.ordid=stocktable.ordid and Acc_PO_HSN_Detail.ordid=Trs_Del2.ordid and Acc_PO_HSN_Detail.styleno=Trs_Del2.StyleNo LEFT OUTER JOIN Trs_Del4 ON Trs_Del2.StockID = Trs_Del4.StockID and Trs_Del2.ID = Trs_Del4.DcID left  outer join Mas_HSN on Mas_HSN.id=Trs_Del4.HSNID left outer Join Mas_Vehicle on Mas_Vehicle.Code=Trs_Salinv.Vehicleid LEFT OUTER JOIN  dbo.Pro_ReqKnitt2 ON Trs_Del2.OrdId = dbo.Pro_ReqKnitt2.OrdId AND Trs_Del1.Prs_Dept = dbo.Pro_ReqKnitt2.DeptId AND StockTable.CntID = dbo.Pro_ReqKnitt2.CntID AND StockTable.ColID = dbo.Pro_ReqKnitt2.ColId AND StockTable.FabID = dbo.Pro_ReqKnitt2.FabId AND StockTable.Gsm = dbo.Pro_ReqKnitt2.GSM AND StockTable.GG = dbo.Pro_ReqKnitt2.GG AND StockTable.ll = dbo.Pro_ReqKnitt2.LL AND  StockTable.FinGsm = dbo.Pro_ReqKnitt2.FinGSM AND StockTable.FinDiaID = dbo.Pro_ReqKnitt2.FinDiaId AND StockTable.PrgKnitGsm = dbo.Pro_ReqKnitt2.GSM AND  StockTable.PrgKnitDiaId = dbo.Pro_ReqKnitt2.DiaID AND StockTable.PRINT_DESIGNID = dbo.Pro_ReqKnitt2.DesignID left outer join Mas_HSN MAs_HSN2 on  Trs_Del4.HSNID=MAs_HSN2.id left outer join  Mas_HSN MAs_HSN3 on  Acc_PO_HSN_Detail.HSNID=MAs_HSN3.id  left outer join Mas_HSN MAs_HSN4 on  Mas_Acc.HSNID=MAs_HSN4.id  inner join ordermas on ordermas.ordid=stocktable.ordid  LEFT OUTER JOIN Mas_Bank Mas_Bank on Mas_Bank.BankId =Mas_Exporter.BankId   left join Mas_SalesGrp on Trs_SalInv.Coycode = Mas_SalesGrp.Coycode  left JOIN SuppOrdMas ON Trs_Del2.SuppOrdid = SuppOrdMas.SuppOrdId  LEFT JOIN Mas_UOM ON Mas_Fabric.PriUomID = Mas_Uom.UomID   WHERE Trs_SalInv.Id=''' + @id + '''  GROUP BY Mas_Exporter.ExporterName, Case When Trs_Salinv.inv_Prefix is Null or Trs_Salinv.inv_Prefix  = '''' then RTRIM(Trs_Salinv.Invno) + ''/'' + RTRIM(Trs_Salinv.Finyear) ELSE RTRIM(Trs_Salinv.inv_Prefix) +''/''+ RTRIM(Trs_Salinv.Invno) + ''/'' + RTRIM(Trs_Salinv.Finyear) END , Trs_Salinv.Finyear, Trs_Salinv.Invdt,Trs_Del1.DocNo,StockTable.YF,Mas_Count.CountName,Mas_Color.ColorDesc,Mas_Fabric.Fabdesc,Trs_Del1.Finyear,Trs_Del1.Dt,Trs_Salinv.ID,Mas_Exporter.CST , Mas_Exporter.TIN ,Mas_Exporter.Phone,Mas_Party.Pname, Mas_Party.Phone ,Mas_Party.CST, Mas_Party.TIN, Mas_Design.DesignDesc, Mas_Buyer.BuyerName, Mas_Buyer.Phone  , Trs_Salinv.PartyType, Mas_Acc.Acc_Descr, cast(Mas_Exporter.ExporterAddress as Varchar), cast(Mas_Party.Paddress as varchar(2000)), Cast(Mas_Buyer.BuyerAddress as Varchar(2000)),isnull(Mas_PartyState.StateName,'''') ,isnull(Mas_PartyState.StateCode,0),isnull(Mas_State.StateName,''''),Isnull(Mas_State.StateCode,0),Mas_HSN.HSNCode,Mas_Exporter.Stateid,Pro_ReqKnitt2.SGSTPer,Mas_Party.Stateid, Pro_ReqKnitt2.CGSTPer,Pro_ReqKnitt2.IGSTPer,Trs_Del1.EwayBillNo,Trs_Del1.EwayBillDt,Pro_ReqKnitt2.Cost,Mas_Exporter.GSTNo,Mas_Party.GSTNo,Mas_Vehicle.VName,Trs_Salinv.ReverseCharge,Trs_Salinv.TransPortationMode,Trs_Del2.Rate,Mas_Count.BrandedFlag,Mas_HSN.UnitRate,Mas_HSN.NBPercH,MaS_HSN.NBPercL,Mas_HSN.BPercH,Mas_HSN.BPercL,Mas_Fabric.BrandedFlag,Mas_HSN2.UnitRate,Mas_HSN2.NBPercH,MaS_HSN2.NBPercL,Mas_HSN2.BPercH,Mas_HSN2.BPercL,Mas_HSN2.HSNCode,MAs_HSN3.UnitRate,MAs_HSN3.NBPercH,MAs_HSN3.NBPercL,MAs_HSN3.BPercH,MAs_HSN3.BPercL,MAs_HSN3.HSNCode,Mas_Party.Paddress,Mas_Exporter.ExporterAddress,Mas_Acc.BrandedFlag,ordermas.Jobno,OrderMas.Finyear, OrderMas.BuyOrdNo, ordermas.OrdId,IsNull(Mas_Bank.CurrAcc,'''')  ,IsNull(Mas_Bank.IFSCCode,''''),IsNull(CostName,'''') ,Trs_Salinv.InvType,Sales_Inv_Yarn_Prefix,Sales_Inv_Fabric_Prefix,Sales_Inv_Acc_Prefix,Trs_Salinv.Invno,Mas_HSN4.UnitRate,Mas_HSN4.NBPercH,MaS_HSN4.NBPercL,Mas_HSN4.BPercH,Mas_HSN4.BPercL,MAs_HSN4.HSNCode,Acc_PO_HSN_Detail.HSNID,isnull(Mas_AccDes.AccDescription,''''),Trs_Salinv.Remarks,Mas_AccDes.AccDescription,SuppOrdMas.SuppNo,SuppOrdMas.SuppFyr,IsNull(Mas_Bank.BankName,''''), isNull(Mas_Uom.Uom,''KGS''),Trs_Del4.CGSTper,Trs_Del4.SGSTper,Trs_Del4.IGSTper'

EXEC sp_executesql @sql1 

END